import java.util.ArrayDeque;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.NavigableSet;
import java.util.TreeSet;

public class DecisionTreeDemo {

    // 1. ArrayDeque as modern high-performance LIFO Stack
    public static void demonstrateModernStack() {
        Deque<String> stack = new ArrayDeque<>();
        stack.push("ROUTE_FIRST");
        stack.push("ROUTE_SECOND");
        stack.push("ROUTE_THIRD");

        System.out.println("Popping from ArrayDeque stack:");
        while (!stack.isEmpty()) {
            System.out.println("  Popped: " + stack.pop());
        }
    }

    // 2. LinkedHashMap as simple LRU (Least Recently Used) cache
    public static void demonstrateLruCache() {
        final int MAX_ENTRIES = 3;
        // accessOrder = true enables LRU eviction order
        Map<String, String> lruCache = new LinkedHashMap<String, String>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                return size() > MAX_ENTRIES;
            }
        };

        lruCache.put("A", "Alpha");
        lruCache.put("B", "Beta");
        lruCache.put("C", "Gamma");
        System.out.println("Initial Cache: " + lruCache.keySet());

        // Access 'A' to promote it
        lruCache.get("A");
        // Insert 'D' - evicts eldest accessed ('B')
        lruCache.put("D", "Delta");
        System.out.println("Cache after accessing 'A' and adding 'D' (B evicted): " + lruCache.keySet());
    }

    // 3. NavigableSet for Sorted Range Queries
    public static void demonstrateRangeQueries() {
        NavigableSet<Integer> scores = new TreeSet<>();
        scores.add(45);
        scores.add(88);
        scores.add(92);
        scores.add(67);
        scores.add(75);

        System.out.println("Scores in range [60, 90]: " + scores.subSet(60, true, 90, true));
        System.out.println("Highest score <= 70: " + scores.floor(70));
        System.out.println("Lowest score >= 70: " + scores.ceiling(70));
    }

    public static void main(String[] args) {
        demonstrateModernStack();
        demonstrateLruCache();
        demonstrateRangeQueries();
    }
}
```

