import java.util.LinkedHashSet;
import java.util.List;

public class OrderedDeduplicator {
    public static LinkedHashSet<String> deduplicatePreservingOrder(List<String> rawTokens) {
        LinkedHashSet<String> result = new LinkedHashSet<>();
        if (rawTokens == null) return result;
        for (String token : rawTokens) {
            if (token != null) {
                result.add(token);
            }
        }
        return result;
    }
}

