import java.util.TreeSet;

public class ScoreBoundaryFinder {
    public static int[] findRangeBounds(TreeSet<Integer> sortedScores, int target) {
        if (sortedScores == null || sortedScores.isEmpty()) {
            return new int[]{-1, -1};
        }
        Integer floor = sortedScores.floor(target);
        Integer ceiling = sortedScores.ceiling(target);
        return new int[]{
            floor != null ? floor : -1,
            ceiling != null ? ceiling : -1
        };
    }
}

